/**
 * F10 End-to-End Playwright Test Suite
 *
 * Selector notes (updated after merging origin/main, UI redesign Nov 2026):
 *  - File upload: `#gallery-input` (hidden <input id="gallery-input">)
 *  - Analyze button: role=button, name /রোগ শনাক্ত করুন/i  (from bn.analyzeBtn)
 *  - Result section: `section[aria-labelledby="result-heading"]`
 *  - Sample tiles: role=button, name /নমুনা ছবি:/
 *  - Navigation links: role=link with Bengali text
 *
 * Tests 5–7 upload real JPG files from web/e2e/fixtures/images/.
 * Tests 8–9 use synthetic images generated by make_fixtures.py.
 * See docs/TEST_REPORT.md for the honest account of what has and has not been
 * tested with real photos.
 */

import { test, expect } from '@playwright/test'
import { existsSync } from 'node:fs'
import { resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const imageFixtures = fileURLToPath(new URL('./fixtures/images/', import.meta.url))

test.describe('F10: AgroLeaf AI End-to-End Test Suite', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/')
  })

  // -----------------------------------------------------------------------
  // Test 1 — App shell loads with disclaimer, 16123, and navigation
  // -----------------------------------------------------------------------
  test('1. App shell loads with disclaimer, 16123, and navigation', async ({ page }) => {
    // Verify product heading
    await expect(page.locator('h1')).toContainText('AgroLeaf AI')

    // Verify 16123 Krishi Call Centre and disclaimer are visible
    await expect(page.getByText('১৬১২৩').first()).toBeVisible()
    // Two elements match /প্রাথমিক স্ক্রিনিং/ (subtitle + disclaimer footer); check the first
    await expect(page.getByText(/প্রাথমিক স্ক্রিনিং/).first()).toBeVisible()

    // Verify 4 navigation tabs
    await expect(page.getByRole('link', { name: 'হোম' })).toBeVisible()
    await expect(page.getByRole('link', { name: 'ইতিহাস' })).toBeVisible()
    await expect(page.getByRole('link', { name: 'কীভাবে কাজ করে' })).toBeVisible()
    await expect(page.getByRole('link', { name: 'সম্পর্কে' })).toBeVisible()
  })

  // -----------------------------------------------------------------------
  // Test 2 — Hash routing navigates seamlessly across all 4 screens
  // -----------------------------------------------------------------------
  test('2. Hash routing navigates seamlessly across all 4 screens', async ({ page }) => {
    // Navigate to History
    await page.click('a[href="#/history"]')
    await expect(page).toHaveURL(/.*#\/history/)
    await expect(page.locator('h1')).toContainText('স্ক্যান ইতিহাস')

    // Navigate to How it works / Accuracy
    await page.click('a[href="#/how-it-works"]')
    await expect(page).toHaveURL(/.*#\/how-it-works/)
    await expect(page.locator('h1')).toContainText('কীভাবে কাজ করে')

    // Navigate to About
    await page.click('a[href="#/about"]')
    await expect(page).toHaveURL(/.*#\/about/)
    await expect(page.locator('h1')).toContainText('সম্পর্কে')

    // Navigate back to Home
    await page.click('a[href="#/"]')
    await expect(page.locator('h1')).toContainText('AgroLeaf AI')
  })

  // -----------------------------------------------------------------------
  // Test 3 — History screen displays empty state with quick link to scan
  // -----------------------------------------------------------------------
  test('3. History screen displays empty state with quick link to scan', async ({ page }) => {
    await page.goto('/#/history')
    await expect(page.locator('h1')).toContainText('স্ক্যান ইতিহাস')
    await expect(page.getByText('কোনো স্ক্যান ইতিহাস নেই')).toBeVisible()

    // Clicking "নতুন পাতা স্ক্যান করুন" returns to home
    await page.click('a:has-text("নতুন পাতা স্ক্যান করুন")')
    await expect(page.locator('h1')).toContainText('AgroLeaf AI')
  })

  // -----------------------------------------------------------------------
  // Test 4 — Sample gallery: FAIL (not skip) when no tiles are present
  //
  // Previously this test used test.skip, which masked the absence of sample
  // tiles.  Per F10 requirements it now FAILS hard if no tile is found.
  // -----------------------------------------------------------------------
  test('4. Sample gallery renders test-split photos and allows instant selection', async ({
    page,
  }) => {
    // Sample gallery cards should be present on home.
    // If the gallery never loads (e.g. samples.json is missing), this will
    // time out and FAIL — which is the correct, honest behaviour.
    const sampleTiles = page.getByRole('button', { name: /নমুনা ছবি:/ })
    await expect(sampleTiles.first()).toBeVisible({ timeout: 15_000 })
    await sampleTiles.first().click()
    // Selected image preview or analyze button should appear
    await expect(page.getByRole('button', { name: /রোগ শনাক্ত করুন/i })).toBeVisible()
  })

  // -----------------------------------------------------------------------
  // Test 5 — Uploads a real blast.jpg and checks result screen safety info
  // Viewport: tested in both Mobile (375 px) and Desktop Chrome projects.
  // -----------------------------------------------------------------------
  test('5. Uploads a real blast photo and checks the result safety information', async ({
    page,
  }) => {
    await page.locator('#gallery-input').setInputFiles(resolve(imageFixtures, 'blast.jpg'))
    const analyzeButton = page.getByRole('button', { name: /রোগ শনাক্ত করুন/i })
    await expect(analyzeButton).toBeVisible()
    await analyzeButton.click()

    const result = page.locator('section[aria-labelledby="result-heading"]')
    await expect(result).toBeVisible({ timeout: 60_000 })
    console.log(`[e2e] blast.jpg result:\n${await result.innerText()}`)

    // Both safety tokens must appear on the result screen
    await expect(result.getByText(/প্রাথমিক স্ক্রিনিং/).first()).toBeVisible()
    await expect(result.getByText('১৬১২৩').first()).toBeVisible()
  })

  // -----------------------------------------------------------------------
  // Test 6 — Runs inference on the other real class sample photos
  // -----------------------------------------------------------------------
  test('6. Runs inference on the other real class sample photos', async ({ page }) => {
    for (const filename of [
      'healthy.jpg',
      'brown_spot.jpg',
      'leaf_smut.jpg',
      'sheath_blight.jpg',
      'tungro.jpg',
    ]) {
      await page.locator('#gallery-input').setInputFiles(resolve(imageFixtures, filename))
      await page.getByRole('button', { name: /রোগ শনাক্ত করুন/i }).click()

      const result = page.locator('section[aria-labelledby="result-heading"]')
      await expect(result).toBeVisible({ timeout: 60_000 })
      await expect(result.getByText(/প্রাথমিক স্ক্রিনিং/).first()).toBeVisible()
      await expect(result.getByText('১৬১২৩').first()).toBeVisible()
      console.log(`[e2e] ${filename} result:\n${await result.innerText()}`)

      if (filename !== 'tungro.jpg') {
        await page.getByRole('button', { name: 'অন্য পাতা পরীক্ষা করুন' }).click()
      }
    }
  })

  // -----------------------------------------------------------------------
  // Test 7 — Uploads a not-rice photo (synthetic sky image) and records
  // what the app actually returned.  The model is not guaranteed to output
  // the "not_rice" tier for a synthetic pixel image — this test records the
  // observed result honestly and verifies only that the safety tokens appear.
  //
  // If a real team-taken not-rice photo (grass.jpg) is present, it is
  // preferred; otherwise the synthetic sky patch is used.
  // -----------------------------------------------------------------------
  test('7. Uploads a not-rice photo and records its observed result', async ({ page }) => {
    // Prefer a real photo; fall back to synthetic
    const realNotRice = resolve(imageFixtures, 'grass.jpg')
    const syntheticNotRice = resolve(imageFixtures, 'not_rice_sky.jpg')
    const photoPath = existsSync(realNotRice) ? realNotRice : syntheticNotRice
    const photoLabel = existsSync(realNotRice) ? 'grass.jpg (real photo)' : 'not_rice_sky.jpg (synthetic — NOT a real photo)'

    await page.locator('#gallery-input').setInputFiles(photoPath)
    await page.getByRole('button', { name: /রোগ শনাক্ত করুন/i }).click()

    const result = page.locator('section[aria-labelledby="result-heading"]')
    await expect(result).toBeVisible({ timeout: 60_000 })

    // Record whatever the model returned — do not assert a specific class
    const resultText = await result.innerText()
    console.log(`[e2e] ${photoLabel} observed result:\n${resultText}`)

    // Safety tokens must always appear
    await expect(result.getByText(/প্রাথমিক স্ক্রিনিং/).first()).toBeVisible()
    await expect(result.getByText('১৬১২৩').first()).toBeVisible()
  })

  // -----------------------------------------------------------------------
  // Test 8 — Rejects non-image files with immediate Bangla error feedback
  // -----------------------------------------------------------------------
  test('8. Rejects non-image files with immediate Bangla error feedback', async ({ page }) => {
    // There are two <input type="file"> elements (#camera-input and #gallery-input).
    // Use #gallery-input with setInputFiles to avoid the strict-mode ambiguity and
    // avoid triggering a native file-chooser dialog (which Playwright cannot control
    // when the input has capture="environment").
    await page.locator('#gallery-input').setInputFiles({
      name: 'report.txt',
      mimeType: 'text/plain',
      buffer: Buffer.from('non-image document content'),
    })

    // Expect validation message in UI
    await expect(page.getByText(/শুধুমাত্র JPG, PNG বা WebP/i)).toBeVisible()
  })
})
